// ─── Seeder ───────────────────────────────────────────────────────────────────

export async function seedReferenceDataIfNeeded(): Promise<void> {
  const db = await getDb();
  if (!db) {
    console.log("[Seed] No database available — skipping reference data seed");
    return;
  }

  try {
    const { prohibitedItems, blacklistedKeywords, restrictedBrands } = await import("../drizzle/schema");

    const [existingProhibited] = await db.select().from(prohibitedItems).limit(1);
    const [existingKeywords] = await db.select().from(blacklistedKeywords).limit(1);
    const [existingBrands] = await db.select().from(restrictedBrands).limit(1);

    let seeded = false;

    if (!existingProhibited) {
      await seedProhibitedItems(PROHIBITED_ITEMS);
      console.log(`[Seed] Inserted ${PROHIBITED_ITEMS.length} prohibited items`);
      seeded = true;
    }

    if (!existingKeywords) {
      // Insert in batches of 500 to avoid DB timeouts
      const BATCH = 500;
      for (let i = 0; i < BLACKLISTED_KEYWORDS.length; i += BATCH) {
        await seedBlacklistedKeywords(BLACKLISTED_KEYWORDS.slice(i, i + BATCH));
      }
      console.log(`[Seed] Inserted ${BLACKLISTED_KEYWORDS.length} blacklisted keywords`);
      seeded = true;
    }

    if (!existingBrands) {
      const BATCH = 200;
      for (let i = 0; i < RESTRICTED_BRANDS.length; i += BATCH) {
        await seedRestrictedBrands(RESTRICTED_BRANDS.slice(i, i + BATCH));
      }
      console.log(`[Seed] Inserted ${RESTRICTED_BRANDS.length} restricted brands`);
      seeded = true;
    }

    if (!seeded) {
      console.log("[Seed] Reference data already populated — no changes made");
    }
  } catch (err) {
    console.error("[Seed] Error seeding reference data:", err);
    // Non-fatal — app continues without seed data
  }
}